INSERT INTO verse_text (verse_id, version_id, text) VALUES (28804, 17, 'Paulo, apóstolo do Cristo Jesus pela vontade de Deus, e o irmão Timóteo, à igreja de Deus que está em Corinto, com todos os Santos que estão na Acaia inteira.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28805, 17, 'Gratidão (graça) a vós, e paz da parte de Deus, nosso Pai, e (da parte) do Senhor Jesus Cristo.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28806, 17, 'Bendito o Deus, e Pai do nosso Senhor Jesus Cristo, o Pai de misericórdias, e Deus de toda consolação;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28807, 17, 'aquele que nos consola em toda a nossa tribulação, para que nós possamos consolar aqueles que (estão) em qualquer (todas) tribulação por meio da consolação com a qual nós mesmos somos consolados por Deus.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28808, 17, 'Porque, assim como são abundantes os sofrimentos de Cristo para nós, assim também é abundante a nossa consolação, por meio do Cristo.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28809, 17, 'Todavia, se somos atribulados, (é) para vossa consolação e salvação; se somos consolados, (é) para a vossa consolação, a qual se torna eficaz,  quando suportais os mesmos sofrimentos que também nós padecemos.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28810, 17, 'A nossa esperança a vosso respeito está firme, sabendo que assim como estais em comunhão nos sofrimentos, assim também (estais) na consolação.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28811, 17, 'Porquanto, não queremos, irmãos, que vós ignoreis o teor da nossa tribulação ocorrida na Ásia, que sobrecarregou-nos de modo excessivo, acima das nossas forças, a ponto de desesperarmos até de viver.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28812, 17, 'Contudo, nós trazemos a sentença de morte em nós mesmos, a fim de que não estejamos confiantes em nós mesmos, mas no Deus que ressuscita os mortos,');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28813, 17, 'o qual nos resgatou e nos resgatará de tão grande morte; em quem, também, temos  esperado que ainda nos resgatará.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28814, 17, 'Cooperando também vós, com as súplicas a nosso favor, para que, por muitas faces, se agradeça (caris, graça) por nós pela dádiva (carisma) que nos foi dada por meio de muitos.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28815, 17, 'Porque o nosso orgulho é este: o testemunho de nossa consciência de que nos conduzimos no mundo - não na sabedoria da carne, mas na caridade (graça) de Deus - com singeleza e pureza de Deus, e especialmente com respeito a vós.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28816, 17, 'Porque nenhuma outra coisa vos escrevemos, exceto as que ledes ou mesmo (as que) compreendeis; e espero que compreendais completamente;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28817, 17, 'como também em parte nos compreendestes, que somos o vosso orgulho, como igualmente vós (sois) o nosso, no dia do nosso Senhor Jesus.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28818, 17, 'Com esta confiança, primeiramente, deliberei ir até vós, a fim de que tivésseis uma segunda dádiva (graça);');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28819, 17, 'e, por vós, atravessar até a Macedônia, e da Macedônia novamente voltar até vós, e ser encaminhado para a Judéia por vós.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28820, 17, 'Todavia, deliberando isto, acaso procedi, então, com leviandade? Ou, as coisas que delibero, segundo a carne delibero, de modo a estar comigo (simultaneamente) o “sim, sim” e o “não, não”?');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28821, 17, 'Ao contrário, “Deus (é) fiel” (*expressão idiomática) que a nossa palavra para convosco não é (simultaneamente) “sim” e “não”.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28822, 17, 'Porquanto o Filho de Deus, Jesus Cristo, que foi, por nós, proclamado entre vós - por mim, Silvano e Timóteo - não foi (simultaneamente) “sim” e “não”, mas nele houve “sim”.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28823, 17, 'Porque quantas (forem) as promessas de Deus, (tantas possuiram) nele o “sim”; porquanto também por ele (é) o “Amém” para glória à Deus, por nosso intermédio.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28824, 17, 'No entanto, Deus é quem nos confirma junto a vós, em Cristo, e (quem) nos ungiu;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28825, 17, 'o qual, não somente nos selou, mas também deu o penhor do Espírito em nossos corações.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28826, 17, 'Invoco, porém, a Deus - testemunha pela minha vida - que, a fim de vos poupar, ainda não fui à Corinto;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28827, 17, 'não que sejamos senhores da vossa fé, mas somos cooperadores do vossa alegria, pois estais firmes pela fé.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28828, 17, 'No entanto, para mim mesmo, decidi isto: não ir novamente até vós com tristeza.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28829, 17, 'Porque, seu eu vos entristeço, quem (será) aquele que me alegra, senão aquele que foi entristecido por mim?');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28830, 17, 'E escrevi estas coisas para que, quando (eu) for, não haja tristeza da parte daqueles que deveriam alegrar-me, confiando - em vós todos - que a minha alegria é a de todos vós.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28831, 17, 'Porquanto, em meio a muita aflição e angústia do coração, com muitas lágrimas, vos escrevi, não para que ficassem entristecidos, mas para conhecerem o amor que tenho em abundância por vós.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28832, 17, 'Todavia, se alguém causou tristeza, não causou tristeza a mim, senão em parte.  Para que (eu) não sobrecarregue a todos vós,');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28833, 17, 'basta para o tal esta repreensão pela maioria;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28834, 17, 'de modo que (deveis), pelo contrário, perdoar e consolar, para que não seja ele, de algum modo, consumido por excessiva tristeza.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28835, 17, 'Exorto-vos, desse modo, a ratificarem para ele o amor.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28836, 17, 'Portanto, para isso também escrevi: para que (eu) conheça o vosso caráter, se sois obedientes em todas as coisas.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28837, 17, 'A quem perdoais alguma coisa, eu também (perdôo); porque, de fato, o que tenho perdoado - se alguma coisa tenho perdoado - por causa de vós (o fiz), diante do Cristo;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28838, 17, 'a fim de que não sejamos ludibriados por Satanás, porquanto não ignoramos os propósitos dele.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28839, 17, 'Ora, quando cheguei a Trôade, para (pregar) o evangelho do Cristo, e abrindo-se para mim uma porta no Senhor,');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28840, 17, 'não tive descanso em meu espírito, pelo fato de eu não ter encontrado o meu irmão Tito. Ao contrário, despedindo-me deles, parti para a Macedônia.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28841, 17, 'No entanto, gratidão (graças) a Deus que, em Cristo, sempre nos conduz em triunfo e, por meio de nós, manifesta a fragrância do conhecimento da sua pessoa (lit. “dele”), em todo lugar.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28842, 17, 'Visto que, para Deus, somos o perfume de Cristo, nos que são salvos e nos que se perdem.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28843, 17, 'Para uns, fragrância de morte para morte, para outros, por sua vez, fragrância de vida para vida. E, para estas coisas, quem é suficiente?');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28844, 17, 'Porque (nós) não somos, como muitos, aqueles que comerciam a palavra de Deus; ao contrário, com sinceridade e da parte de Deus, falamos em Cristo na presença de Deus.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28845, 17, 'Começamos, novamente, a recomendarmos a nós próprios? Será que necessitamos, como alguns, de cartas de recomendação para vós, ou de vós?');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28846, 17, 'Vós sois a nossa carta, inscrita em nossos corações, conhecida e lida por todos os homens.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28847, 17, 'Está manifesto que sois carta de Cristo, ministrada por nós, inscrita não com tinta, mas com o Espírito do Deus vivo (que vive); não em tábuas de pedra, mas nas tábuas de carne dos corações.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28848, 17, 'E (é) por intermédio do Cristo que temos tal confiança em Deus;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28849, 17, 'não que, por nós mesmos, sejamos capazes de pensar alguma coisa, como proveniente de nós mesmos, mas nossa capacidade provêm de Deus;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28850, 17, 'o qual também nos capacitou (qualificou) como ministros de uma nova aliança, não da letra, mas do Espírito; porquanto a letra mata, mas o Espírito vivifica.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28851, 17, 'E, se o ministério da morte, gravado com letras em pedras, veio em glória, a ponto de os filhos de Israel não poderem fitar o rosto de Moisés, por causa da glória do rosto dele - que (mesmo assim) se desvanecia -,');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28852, 17, 'como não será de maior glória o ministério do Espírito?');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28853, 17, 'Porque, se para o ministério da condenação (houve) glória, muito mais será abundante, em glória, o ministério da justificação.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28854, 17, 'Porquanto, o que foi glorificado, em certa medida não foi glorificado, por causa desta superabundante glória;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28855, 17, 'Se, portanto, o que se desvanecia (teve) glória, muito mais glória tem o que é permanente.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28856, 17, 'Tendo, pois, tal esperança, fazemos uso de muita ousadia na fala.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28857, 17, 'E, não (procedemos) conforme Moisés, que colocava um véu sobre o seu rosto para que os filhos de Israel não fitassem o término (conclusão que evoca uma finalidade previamente estabelecida) do que se desvanecia.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28858, 17, 'Mas os sentidos (percepções) deles foram endurecidos. Pois até ao dia de hoje, permanece o mesmo véu sobre a leitura da antiga aliança, não (lhes) sendo revelado que (ela - a antiga aliança) se desvanece por conta do Cristo.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28859, 17, 'A contrário, até hoje, toda vez que Moisés é lido, está posto um véu sobre o coração deles.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28860, 17, 'Todavia, se retornarem (teshuvá) para o Senhor, o véu é removido.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28861, 17, 'Ora, o Senhor é o Espírito; e, onde (está) o Espírito do Senhor (há) liberdade.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28862, 17, 'E, todos nós, com o rosto desvendado, refletindo, como por espelho, a glória do Senhor, somos transformados, de glória em glória, conforme a própria imagem do Espírito do Senhor.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28863, 17, 'Por isso, tendo este ministério, segundo a misericórdia recebida, não desanimamos;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28864, 17, 'Ao contrário, renunciamos as coisas vergonhosas que estão ocultas (lit.  hebraísmo “coisas ocultas da vergonha”), não andando com astúcia, nem falsificando a palavra de Deus; mas nos recomendando à consciência de todo homem, na presença de Deus, pela manifestação da verdade.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28865, 17, 'Todavia, se o nosso evangelho ainda está encoberto, está encoberto para os que se perdem (perecem),');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28866, 17, 'para aqueles a quem o Deus desta era cegou os sentidos (percepções) - dos que não crêem - para não perceberem a luz do evangelho da glória do Cristo - que é imagem de Deus.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28867, 17, 'Porquanto, não proclamamos a nós mesmos, mas ao Senhor Jesus Cristo; a nós mesmos, (nos proclamamos) vossos servos, por causa de Jesus.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28868, 17, 'Porque o Deus que disse: “A Luz brilhará a partir das trevas” é quem brilhou em nossos corações, para iluminação do conhecimento da glória de Deus, na face do Cristo.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28869, 17, 'Temos, porém, este tesouro em vasos de barro, a fim de que a excelência do poder seja de Deus, e não de nós (mesmos).');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28870, 17, 'Em tudo (estamos) atribulados, mas não imobilizados (restringidos, confinados); perplexos, mas não desesperados;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28871, 17, 'perseguidos, mas não abandonados; derrubados, mas não destruídos;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28872, 17, 'portando sempre no corpo a mortificação (ação de morrer) de Jesus, a fim de que a vida de Jesus também seja manifestada em nosso corpo.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28873, 17, 'Porquanto, nós - os que estamos vivos - sempre somos entregues à morte, por causa de Jesus, a fim de que a vida de Jesus seja manifestada em nossa carne mortal.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28874, 17, 'De modo que, em nós, opera a morte, mas em vós, a vida.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28875, 17, 'Tendo, porém, o mesmo espírito da fé, conforme está escrito: “Cri, por isso falei” . Nós também cremos, por isso também falamos.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28876, 17, 'Sabendo que aquele que ressuscitou (ergueu) o Senhor Jesus, também a nós, com Jesus, ressuscitará, e nos apresentará convosco.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28877, 17, 'Porque, tudo isso é por vós, para que a caridade (graça), tornada plena por intermédio de muitos, torne abundante os atos de gratidão (ação de graças), para a glória de Deus.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28878, 17, 'Assim, não desanimamos; ao contrário, se o nosso homem exterior perece, o nosso (homem) interior se renova dia a dia.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28879, 17, 'Pois a nossa tribulação produz para nós, mais e mais abundantemente, um eterno peso de glória.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28880, 17, 'Não atentando nas coisas visíveis, mas nas coisas invisíveis; pois as coisas visíveis são transitórias, mas aquelas que não (são) visíveis (são) eternas.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28881, 17, 'Sabemos, portanto, que se a nossa casa terrena (sobre a terra) - tenda (do tabernáculo) - for destruída, temos uma edificação de Deus - casa não feita por mãos, eterna, nos céus.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28882, 17, 'Assim, (é) por esta razão, também, que gememos, ansiando (intensamente) sermos revestidos da nossa habitação - a proveniente do céu -');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28883, 17, 'Se, de fato, formos encontrados despidos, (mas) não nus.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28884, 17, 'Porquanto, (nós) - que estamos na tenda (tabernáculo) - gememos, sobrecarregados, não porque queremos ser despidos, mas (porque queremos) ser revestidos, a fim de que o mortal seja absorvido pela vida.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28885, 17, 'E quem nos preparou para isto (é) o próprio Deus, que nos deu o  penhor do Espírito.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28886, 17, 'Sendo assim, sempre confiantes, e sabendo que, estando presentes no corpo, estamos ausentes do Senhor;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28887, 17, 'andamos, pois, pela fé, não por visão.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28888, 17, 'Desse modo, confiamos e preferimos muito mais estar ausentes do corpo, porém, presentes junto ao Senhor;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28889, 17, 'Por isso, também, quer estando presentes, quer estando ausentes, temos por ambição ser agradáveis a ele.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28890, 17, 'Pois, é necessário que todos nós sejamos apresentados diante do Tribunal do Cristo, a fim de que cada um receba conforme as coisas que, por meio do corpo, praticou, quer seja o bem, quer seja o mal.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28891, 17, 'Assim, conhecendo o temor do Senhor, persuadimos os homens, mas fomos apresentados a Deus; e espero, também, sermos apresentados às vossas consciências.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28892, 17, 'Não nos recomendamos novamente a vós outros; pelo contrário, damos a vós o ensejo de vos gloriardes por nossa causa, para que tenhais o que responder ao que se gloriam na aparência e não no coração.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28893, 17, 'Porque, se enlouquecemos, (é) para Deus; e, se conservamos o juízo, (é) para vós.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28894, 17, 'Pois, o amor de Cristo nos constrange, julgando (nós) isto: um morreu por todos; logo, todos morreram.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28895, 17, 'E ele morreu por todos, a fim de que os que vivem não vivam mais para si mesmos, mas para aquele que por eles morreu e foi ressuscitado (erguido).');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28896, 17, 'Sendo assim, a partir da agora, a ninguém conhecemos segundo a carne; e, se (antes) conhecemos Cristo segundo a carne, agora não mais o conhecemos (deste modo).');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28897, 17, 'Desse modo, se alguém (está) em Cristo, (é) nova criatura; as coisas antigas passaram; eis que se fizeram novas.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28898, 17, 'Todas as coisas, porém, provêm de Deus, que nos reconciliou consigo mesmo por meio de Cristo, e nos deu o ministério da reconciliação;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28899, 17, 'de modo que Deus estava, em Cristo, reconciliando o mundo consigo mesmo, não atribuindo a eles as suas transgressões, mas colocando em nós a palavra da reconciliação.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28900, 17, 'De sorte que, somos embaixadores, por Cristo, como se Deus exortasse por nosso intermédio. Portanto, pelo Cristo, rogamos que vos reconcilieis com Deus.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28901, 17, 'Aquele que não conheceu pecado, ele (Deus) o fez pecado por nós; a fim de que, nele, nos tornássemos justiça de Deus.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28902, 17, 'Cooperando, também vos exortamos a não receberdes em vão a caridade (graça) de Deus,');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28903, 17, 'porque diz: “Na ocasião favorável te ouvi, e no dia da salvação te socorri”. Eis agora a ocasião aceitável, eis agora o dia da salvação.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28904, 17, 'Não dando nós nenhum motivo de tropeço em nada, a fim de que o ministério não seja censurado.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28905, 17, 'Pelo contrário, em tudo recomendando a nós mesmos como ministros de Deus: em muita fortaleza, em tribulações, em necessidades, em angústias,');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28906, 17, 'em açoites, em prisões, em tumultos, em labutas, em vigílias, em jejuns,');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28907, 17, 'em pureza, em conhecimento, em longanimidade, em bondade, em Espírito Santo, em amor não hipócrita,');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28908, 17, 'em palavra de verdade, em poder de Deus; pelas armas da justiça - as da (mão) direita, e as da (mão) esquerda;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28909, 17, 'por glória, e por desonra; por má reputação e por boa reputação; como enganadores e verdadeiros;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28910, 17, 'como desconhecidos, e bem conhecidos; como se estivéssemos morrendo e, contudo, eis que vivemos; como castigados, porém não mortos,');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28911, 17, 'como estando tristes, mas sempre alegres; como pobres, mas enriquecendo a muitos; como nada tendo, mas possuindo todas as coisas.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28912, 17, 'A nossa boca se abriu para vós, Coríntios; o nosso coração se ampliou;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28913, 17, 'não estais restritos a nós, mas estais limitados em vossos corações.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28914, 17, 'Porquanto, (tendes) a mesma retribuição - falo-vos como a filhos - ampliai-vos também vós.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28915, 17, 'Não estejais em jugo desigual com não crentes; pois que participação (têm) a justiça com a injustiça? Ou, que comunhão (possui) a luz com as trevas?');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28916, 17, 'E que harmonia (há) entre Cristo e Beliar? Ou, que parte (têm) o crente com o não crente?');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28917, 17, 'E que acordo (há) entre o Santuário de Deus e os ídolos? Porque nós somos o Santuário de Deus que vive, como disse Deus: “Habitarei neles, andarei entre eles, e eles serão meu povo”.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28918, 17, 'Por isso: “Saí do meio deles, e sede separados”, diz o Senhor: “e não toqueis coisa impura;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28919, 17, 'e eu vos receberei, e serei para vós Pai, e vós sereis para mim Filhos”  e Filhas, diz o Senhor Todo-Poderoso.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28920, 17, 'Portanto, amados, tendo estas promessas, purifiquemos a nós mesmos de toda impureza, da carne e do espírito, completando a santificação no temor à Deus.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28921, 17, 'Acolhei-nos; a ninguém tratamos com injustiça, a ninguém corrompemos, a ninguém exploramos.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28922, 17, 'Não falo para condenação, porque (vos) disse anteriormente que estais em nossos corações para morrermos juntos e vivermos (juntos).');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28923, 17, 'Grande (é) a ousadia da minha fala para convosco; (é) grande o meu orgulho a vosso respeito. Estou repleto de consolação, transbordo de alegria em toda a nossa tribulação.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28924, 17, 'Porque, chegando à Macedônia, nenhum alívio teve a nossa carne; pelo contrário, em tudo fomos atribulados - lutas por fora, temores por dentro.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28925, 17, 'Deus, porém, que consola os abatidos, nos consolou com a chegada de Tito;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28926, 17, 'e não somente com a chegada dele, mas também com a consolação com que foi consolado por vós, relatando-nos a vossa saudade, o vosso pranto, o vosso zelo por mim, a ponto de eu me alegrar ainda mais.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28927, 17, 'Porque, se também vos entristeci com a carta, não me arrependo; se me arrependi, ao ver que aquela carta vos entristeceu, ainda que por pouco tempo;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28928, 17, 'agora, me alegro, não porque fostes entristecidos, mas porque fostes entristecidos para mudança de mentalidade; pois fostes entristecidos segundo Deus, para que em nada sofrêsseis dano de nossa parte.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28929, 17, 'Porque a tristeza segundo Deus produz mudança de mentalidade para salvação, sem arrependimento (de ninguém); mas a tristeza do mundo produz a morte.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28930, 17, 'Vede! Quanto diligência (não) produziu isto mesmo em vós - estar entristecido segundo Deus! (Não somente isso), mas (quanta) defesa, (quanta) indignação, (quanto) temor, mas (quanta) saudade, (quanto) zelo, (quanta) vingança! Em tudo destes demonstração de estardes puros nesse assunto.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28931, 17, 'Então, se vos escrevi, não foi por causa do ofensor, nem por causa do ofendido, mas por causa da vossa solicitude por nós, manifestada entre vós, diante de Deus.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28932, 17, 'Por isso fomos consolados. E acima da nossa consolação, nos alegramos mais abundantemente ainda com a alegria de Tito, porque o espírito dele foi acalmado por todos vós.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28933, 17, 'Porque, se algo exaltei a vosso respeito para ele, não me envergonhei; ao contrário, como em tudo vos falamos com verdade, assim também a nossa exaltação, perante Tito, se tornou verdade.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28934, 17, 'E o afeto dele por vós transbordou, lembrando-se da obediência de todos vós, de como o recebestes com temor e tremor.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28935, 17, 'Alegro-me, porque em tudo confio em vós.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28936, 17, 'Também, Irmãos, vos damos a conhecer a caridade (graça) de Deus dada às igrejas da Macedônia;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28937, 17, 'porque, em meio a muita prova (teste) de tribulação, (manifestou-se) a abundância da alegria deles, e a profunda pobreza deles superabundou na grande riqueza da sua generosidade.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28938, 17, 'Porque, segundo o seu poder - (o que eu mesmo) testifico -, e ainda acima do (seu) poder, (deram) voluntariamente;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28939, 17, 'pedindo-nos, com muitos apelos, (participarem) na caridade (graça) e na comunhão do serviço para com os Santos.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28940, 17, 'E não (somente fizeram) como nós esperávamos, mas também deram-se a si mesmos - primeiramente ao Senhor, depois a nós - pela vontade de Deus;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28941, 17, 'de maneira que exortamos a Tito que, conforme começou anteriormente, assim também complete em vós esta caridade (graça).');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28942, 17, 'Portanto, como em tudo sois abundantes - tanto na fé e na palavra como no saber, e em toda solicitude, e em nosso amor para convosco - assim também sejais abundantes nesta caridade (graça).');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28943, 17, 'Falo, não segundo um comando, mas para provar, pela diligência de outros, a sinceridade do vosso amor;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28944, 17, 'pois conheceis a caridade (graça) do nosso Senhor Jesus Cristo que, por causa de vós, se fez pobre, (mesmo) sendo rico, a fim de que vós, pela pobreza dele, vos tornásseis ricos.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28945, 17, 'E nisto dou (minha) opinião, pois isto vos convém; vós que começastes, desde o ano passado, não somente a fazer mas também a querer.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28946, 17, 'Completai, agora, o que (ainda) há por fazer, para que, assim como (houve) prontidão do querer, (haja) também o cumprimento (término), a partir do que tendes.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28947, 17, 'Porquanto, se está presente a prontidão (do querer), (será) aceitável segundo aquilo que alguém tiver, não segundo aquilo que não tem.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28948, 17, 'Assim, não (digo isso) a fim de que (haja) alívio para os outros, e aflição para vós; mas, (partindo) da igualdade,');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28949, 17, '(que) a vossa abundância (supra), no tempo presente, a carência daqueles; de modo que a abundância deles (supra) também a vossa carência, a fim de que haja igualdade,');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28950, 17, 'como está escrito: “O que muito (colheu) não teve demais, e o que (colheu) pouco não teve de menos”.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28951, 17, 'Gratidão (graças) a Deus, aquele que deu ao coração de Tito o mesmo zelo por vós,');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28952, 17, 'porque ele aceitou a exortação, e sendo muito diligente, partiu voluntariamente para vós.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28953, 17, 'E com ele enviamos aquele irmão cujo louvor no Evangelho (está disseminado) por todas as Igrejas.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28954, 17, 'E não somente (isso), mas foi também eleito por todas as Igrejas para (ser) nosso companheiro de viagem, com esta caridade (graça) ministrada por nós para a glória do próprio Senhor, e por nossa solicitude.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28955, 17, 'Evitando isto: que alguém nos acuse em razão desta generosa dádiva por nós ministrada;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28956, 17, 'pois consideramos as coisas boas, não somente diante do Senhor, mas também diante dos homens.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28957, 17, 'E enviamos com eles o nosso irmão, o qual comprovamos, muitas vezes, ser diligente em muitas coisas; e agora muito mais diligente, (por causa) da muita confiança (depositada) em vós.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28958, 17, 'Quanto a Tito, (é) meu companheiro e cooperador junto a vós; quanto a nossos irmãos, (são) apóstolos (enviados) das Igrejas, glória de Cristo.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28959, 17, 'Portanto, demonstrai a eles, perante as Igrejas, a prova do vosso amor e nosso orgulho por vós.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28960, 17, 'A respeito da administração (referência à coleta) em favor dos Santos, é desnecessário escrever a vós.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28961, 17, 'Porquanto conheço a vossa solicitude, da qual (eu) me glorio junto aos Macedônios a vosso respeito; (dizendo) que Acaia está preparada desde o ano passado, e o vosso zelo incitou a muitos.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28962, 17, 'Contudo, enviei os irmãos, para que o nosso orgulho, a vosso respeito, não seja vão nesta parte; para que - como eu dizia - estejais preparados;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28963, 17, 'para que, se os Macedônios vierem comigo e vos encontrarem despreparados, nós não sejamos envergonhados - para não dizer vós - nesta (nossa) confiança.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28964, 17, 'Portanto, considerei necessário exortar os irmãos para que primeiro fossem até vós, preparassem de antemão a vossa benção (oferta), previamente anunciada, para que ela seja preparada como benção (oferta) e não como avareza.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28965, 17, 'E digo isto: O que semeia parcamente, parcamente também colherá; e o que semeia generosamente, generosamente colherá.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28966, 17, 'Cada um conforme se propôs em seu coração, não com tristeza ou por necessidade; porque Deus ama o doador alegre.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28967, 17, 'E, Deus pode tornar abundante para vós toda a caridade (graça), a fim de que, tendo sempre, em tudo, todo o suficiente, abundeis em toda boa obra;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28968, 17, 'como está escrito: “Distribuiu, deu aos pobres, a sua justiça permanece para sempre”.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28969, 17, 'Ora, aquele que fornece semente ao que semeia, e pão para alimento, fornecerá e multiplicará a vossa semente, aumentará os frutos da vossa justiça.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28970, 17, 'Enriquecendo-vos, em tudo, para toda generosidade, a qual produz, por nosso intermédio, gratidão (eucaristia, ação de graças) à Deus.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28971, 17, 'Porque a administração deste serviço não somente supre as necessidades dos Santos, mas também redunda em muita gratidão (eucaristia, ação de graças) à Deus.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28972, 17, 'Por meio deste ministério (administração), glorificam a Deus, por conta da submissão - que confessais - ao Evangelho de Cristo, e por conta da singeleza da comunhão com eles e com todos.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28973, 17, 'E eles, em súplica por vós, anseiam por vós, por causa da superabundante caridade (graça) de Deus sobre vós.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28974, 17, 'Gratidão (graças) a Deus pela indescritível dádiva (dom).');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28975, 17, 'E eu mesmo, Paulo, vos rogo, pela mansidão e equidade do Cristo - eu que, quando presente entre vós, sou humilde; mas, quando ausente, ousado para convosco -');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28976, 17, 'peço para não (ter que) ser ousado, quando estiver presente (entre vós), com a segurança com que considero ser ousado diante de alguns - aqueles que nos consideram semelhantes aos que andam segundo a carne -');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28977, 17, 'pois, embora andemos na carne, não combatemos segundo a carne.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28978, 17, 'Porquanto, as armas do nosso combate não (são) carnais, mas poderosas em Deus para a destruição de fortalezas; destruindo (nós) argumentos (falsos)');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28979, 17, 'e toda altivez que se levante contra o conhecimento de Deus; e levando, cativo, todo entendimento (percepção) à obediência de Cristo;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28980, 17, 'estando prontos para punir toda desobediência, quando for plena a vossa obediência.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28981, 17, 'Observais as coisas segundo as aparências? Se alguém está convencido, em si mesmo, que é do Cristo, considere novamente em si mesmo que, assim como ele é do Cristo, do mesmo modo, também nós (somos).');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28982, 17, 'Porque, se eu me orgulhar um pouco mais abundantemente a respeito da nossa autoridade - a qual nos deu o Senhor para edificação e não para a vossa destruição - ficarei envergonhado;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28983, 17, 'para que não pareça (ser meu intuito) intimidar-vos por meio de cartas.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28984, 17, 'Porque diz (alguém): As cartas são pesadas e fortes, todavia a “presença do corpo” (presença pessoal) é fraca, e a fala desprezível.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28985, 17, 'Considere tal (pessoa) isto: tal como somos na palavra por cartas, estando ausentes, tal seremos na ação, estando presentes.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28986, 17, 'Porque não ousamos classificar-nos ou comparar-nos com alguns que se recomendam a si próprios; mas eles, medindo-se consigo mesmos e comparando-se consigo mesmos, não compreendem.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28987, 17, 'Nós, porém, não nos orgulharemos incomensuravelmente, mas segundo a medida (metro) do padrão que Deus repartiu para nós.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28988, 17, 'Porquanto não nos excedemos, como se não (devêssemos) chegar até vós, posto que já chegamos (até) vós com o Evangelho do Cristo;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28989, 17, 'não nos orgulhando desmedidamente nos labores alheios, mas tendo esperança de que, crescendo a vossa fé, seremos abundantemente engrandecidos entre vós, segundo o nosso padrão.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28990, 17, 'para evangelizar nas (regiões) que (estão) além de vós, para não nos orgulharmos das coisas feitas em território de outrem.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28991, 17, 'Aquele, porém, que se orgulha, que se orgulhe no Senhor.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28992, 17, 'Pois não é aprovado quem a si mesmo se recomenda, mas aquele a quem o Senhor recomenda.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28993, 17, 'Quem dera suportásseis um pouco minha loucura! Suportai-me, porém, ainda.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28994, 17, 'Porque (eu) zelo por vós com zelo de Deus; porquanto, ao  vos apresentar a Cristo, vos prometi em casamento, como virgem pura, a um marido.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28995, 17, 'Temo, porém, que de algum modo, assim como a serpente - na astúcia dela - enganou a Eva, (também) sejam corrompidos os vossos sentidos (percepção, mente), (apartando-vos) da simplicidade que há em Cristo.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28996, 17, 'Portanto, se alguém vier proclamar outro Jesus, que não tenhamos proclamado; ou (se) estais recebendo outro Espírito que não recebestes, ou outro Evangelho que não acolhestes, então, sendo assim, estais tolerando de bom grado.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28997, 17, 'Porquanto, (eu) considero não ser inferior em nada aos mais excelentes apóstolos.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28998, 17, 'E, embora (eu seja) amador na fala, não (sou) no conhecimento; ao contrário, temos nos manifestado completamente a vós, em todas as coisas.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (28999, 17, 'Porventura, cometi pecado humilhando a mim mesmo para que vós fosseis exaltados? Porque vos anunciei o Evangelho de Deus gratuitamente?');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29000, 17, 'Outras igrejas despojei, recebendo (delas) salário para o vosso serviço (ministério);');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29001, 17, 'e estando convosco, mesmo necessitado, não fui pesado a ninguém; pois os irmãos vindos da Macedônia supriram a minha necessidade, e em tudo me guardei - sem ser pesado para vós - e me guardarei.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29002, 17, '(Asseguro pela) verdade de Cristo que está em mim que este meu orgulho não será calado nas regiões da Acaia.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29003, 17, 'Por que? Porque não vos amo? Deus (o) sabe.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29004, 17, 'Todavia, o que faço, e farei, (é) para remover a oportunidade dos que desejam uma oportunidade; para que sejam encontrados como nós, naquilo em que se orgulham.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29005, 17, 'Porque os tais são falsos apóstolos, obreiros fraudulentos, transformando-se em apóstolos do Cristo.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29006, 17, 'E não (é nenhuma) maravilha, pois ele mesmo - Satanás - se transforma em anjo de luz.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29007, 17, 'Não (é) grande (coisa), portanto, que também os servos dele se transformem em ministros da justiça; o fim deles será segundo suas obras.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29008, 17, 'Digo novamente, que ninguém pense que sou tolo; se o for, mesmo assim, recebei-me como tolo, a fim de que eu também me orgulhe um pouco -');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29009, 17, 'o que falo, não falo segundo o Senhor, mas como em tolice, nesta confiança do orgulho -');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29010, 17, 'visto que muitos se orgulham segundo a carne, também eu me orgulharei.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29011, 17, 'Porquanto, sendo (vós) sábios, tolerais alegremente os tolos.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29012, 17, 'Tolerais, assim, quando alguém vos escraviza, quando alguém (vos) devora, quando alguém toma de vós, quando alguém se exalta, quando alguém vos bate no rosto');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29013, 17, 'Digo com vergonha: como temos sido fracos; mas, naquilo que alguém é ousado - falo com insensatez - também eu sou ousado.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29014, 17, 'São Hebreus? Também eu. São Israelitas? Também eu. São descendência de Abraão? Também eu.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29015, 17, 'São servidores de cristo? muito mais eu - falo delirando - muito mais em labutas; muito mais em prisões; muitíssimo mais em açoites; em perigos de morte muitas vezes;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29016, 17, 'Recebi cinco vezes do Judeus os “quarenta menos um” açoites;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29017, 17, 'três vezes apanhei com varas; uma vez fui apedrejado; três vezes naufraguei; um dia e uma noite passei no abismo (mar alto);');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29018, 17, 'em viagens, muitas vezes; em perigos de rios; em perigos de salteadores; em perigos provenientes (dos da minha) raça; em perigos de gentios; em perigos na cidade; em perigos no deserto; em perigos no mar; em perigos entre os falsos irmãos;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29019, 17, 'em labuta e em fadiga, em vigílias muitas vezes; em fome e sede, em jejuns muitas vezes; em frio e nudez;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29020, 17, 'Além das coisas exteriores, há a pressão sobre mim, a cada dia: a preocupação com todas as igrejas.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29021, 17, 'Quem enfraquece, e eu não enfraqueço? Quem se escandaliza, e eu não me inflamo?');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29022, 17, 'Se é necessário me orgulhar, naquilo que diz respeito à minha fraqueza me orgulharei.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29023, 17, 'O Deus e Pai do Senhor Jesus - aquele que é bendito para sempre - sabe que não minto.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29024, 17, 'Em Damasco, o Etnarca (preposto) do Rei Aretas montou guarda na cidade dos Damascenos para me prender;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29025, 17, 'mas, por uma janela, fui baixado em um cesto, através da muralha, e escapei das mãos dele.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29026, 17, 'É necessário orgulhar-me? Por certo, não convém. No entanto, passarei às visões e revelações do Senhor.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29027, 17, 'Conheço um homem em Cristo que há quatorze anos - se no corpo, não sei; se fora do corpo, não sei; Deus o sabe - foi carregado ao terceiro céu.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29028, 17, 'E sei que o tal homem - se no corpo, se sem o corpo, não sei; Deus o sabe -');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29029, 17, 'foi carregado ao paraíso, e ouviu indizíveis palavras, às quais não é lícito a um homem falar.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29030, 17, 'Por esse alguém me orgulharei, mas por mim mesmo não me orgulharei, senão nas fraquezas.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29031, 17, 'Pois, se eu quiser me orgulhar, não serei tolo, porquanto falarei a verdade; todavia, me abstenho para que ninguém considere em mim além daquilo que vê em mim, ou ouve de mim;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29032, 17, 'e também pela grandeza das revelações. Por isso - para não me exaltar demais - me foi dado algo pontiagudo na carne, mensageiro de Satanás, a fim de me golpear, para que eu não me exalte demais.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29033, 17, 'A respeito disso, três vezes pedi ao Senhor para que (ele) afastasse (isso) de mim.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29034, 17, 'E me disse: Basta a ti a minha caridade (graça), pois o poder (dínamis) se aperfeiçoa na fraqueza; portanto, muito alegremente, me orgulharei ainda mais nas minhas fraquezas, a fim de que o poder (dínamis) de Cristo arme um tenda (habite) sobre mim.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29035, 17, 'Por isso me comprazo nas fraquezas, nos insultos, nas necessidades, nas perseguições, nas limitações (estreito, apertado) por Cristo; porquanto, quando me enfraqueço, então sou forte.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29036, 17, 'Tornei-me tolo; vós me obrigastes. Eu, porém, deveria ser recomendado por vós, pois em nada fui inferior aos mais excelentes apóstolos, ainda que eu nada seja.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29037, 17, 'De fato, os sinais de apóstolo foram produzidos entre vós, com toda robustez; sinais, e também prodígios e atos de poder (dínamis).');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29038, 17, 'Pois, em que fostes tratados como inferiores às demais igrejas, exceto no fato de eu não ter sido um peso para vós? Perdoai-me esta injustiça.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29039, 17, 'Eis que esta é a terceira vez que estou preparado para ir até vós, e não serei um peso; pois não busco o que é vosso, mas a vós (mesmos); porquanto, não devem os filhos entesourar para os pais, mas os pais para os filhos.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29040, 17, 'Eu, mais alegremente ainda, gastarei e serei gasto por vossas almas. Ainda que, amando-vos mais intensamente, (eu) seja menos amado.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29041, 17, 'Seja assim! Eu, porém, não fui um peso para vós. Ao contrário, sendo astuto, vos prendi com dolo.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29042, 17, 'Será que, por meio daqueles que vos envie, (eu) vos explorei (tirar vantagem)?');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29043, 17, 'Roguei a Tito, e enviei com ele (outro) irmão. Será que Tito vos explorou? Acaso, não temos andado no mesmo espírito? Não seguimos nas mesmas pisadas?');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29044, 17, 'Há muito, pensais que estamos nos desculpando perante vós. Amados,  em Cristo, falamos todas as coisas, perante Deus, para a vossa edificação.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29045, 17, 'Pois, temo que, ao chegar, eu não vos encontre como quero, e também não seja encontrado por vós tal como desejais; (temo) que, de algum modo, (haja) contenda, inveja, iras, rivalidades, maledicências, fofocas, arrogância e revoltas (desordem);');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29046, 17, 'e, quando eu for, o meu Deus não me humilhe junto a vós, e eu chore por muitos dos que pecaram anteriormente, mas não se arrependeram pela impureza, imoralidade e libertinagem que praticaram.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29047, 17, 'Esta (é) a terceira vez que vou até vós; pela boca de duas testemunhas ou de três será decidida toda questão.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29048, 17, '(Eu) disse antes, e digo antecipadamente - de modo semelhante quando estava presente na segunda vez, embora ausente agora - a todos os demais - os que pecaram anteriormente - que, se (eu) for outra vez, não pouparei;');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29049, 17, 'visto que buscais uma prova de que Cristo fala em mim, ele que não é fraco convosco; ao contrário, é poderoso em vós.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29050, 17, 'Porque, de fato, foi crucificado em fraqueza; contudo, vive pelo poder de Deus. Assim também, nós somos fracos nele, mas viveremos, com ele, para vós outros, pelo poder de Deus.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29051, 17, 'Examinai a vós mesmos se estais na fé; provai a vós mesmos. Ou não reconheceis, para vós mesmos, que Jesus Cristo está em vós? A não ser que estejais reprovados.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29052, 17, 'Espero, porém, que saibam que nós não estamos reprovados.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29053, 17, 'E estamos orando à Deus para que vós não façais mal algum, não para que nós pareçamos aprovados, mas para que vós façais o bem; embora nós sejamos tidos como reprovados.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29054, 17, 'Porque nada podemos contra a verdade, senão a favor da verdade.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29055, 17, 'Portanto, sempre nos alegramos por sermos fracos, embora vós sejais fortes. E oramos por isto: o vosso aperfeiçoamento.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29056, 17, 'Por isso escrevo estas coisas, estando ausente, para que, estando presente, não proceda severamente, segundo a autoridade que o Senhor me deu: para edificação e não para destruição.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29057, 17, 'De resto, irmãos, alegrai-vos, sede aperfeiçoados, sede consolados, pensai do mesmo modo, vivei em paz, e o Deus do amor e da paz estará convosco.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29058, 17, 'Saudai-vos uns aos outros com ósculo santo. Todos os santos vos saúdam.');
INSERT INTO verse_text (verse_id, version_id, text) VALUES (29059, 17, 'A caridade (graça) do Senhor Jesus Cristo, o amor de Deus, e a comunhão do Santo Espírito (sejam) com todos vós.');